import React, { useState } from 'react';
import DatePicker from 'react-datepicker';
import { format, addDays, isAfter, isBefore } from 'date-fns';
import { FaCalendarAlt, FaClock, FaArrowRight } from 'react-icons/fa';
import 'react-datepicker/dist/react-datepicker.css';

const DateSelection = ({ onComplete, onBack }) => {
  const [startDate, setStartDate] = useState(null);
  const [endDate, setEndDate] = useState(null);
  const [startTime, setStartTime] = useState(null);
  const [endTime, setEndTime] = useState(null);

  const handleStartDateChange = (date) => {
    setStartDate(date);
    // If end date is before start date, update it
    if (endDate && isBefore(endDate, date)) {
      setEndDate(date);
    }
  };

  const handleEndDateChange = (date) => {
    setEndDate(date);
  };

  const handleComplete = () => {
    if (startDate && endDate && startTime && endTime) {
      onComplete({
        startDate,
        endDate,
        startTime,
        endTime
      });
    }
  };

  const isComplete = startDate && endDate && startTime && endTime;

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow-sm">
        <div className="max-w-7xl mx-auto px-4 py-4">
          <h1 className="text-2xl font-bold text-gray-900">Select Your Dates</h1>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-3xl mx-auto px-4 py-8">
        <div className="bg-white rounded-lg shadow-lg p-6">
          {/* Date Selection */}
          <div className="space-y-6">
            <div className="flex items-center space-x-4">
              <FaCalendarAlt className="text-blue-500 text-xl" />
              <h2 className="text-xl font-semibold">Select Dates</h2>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Start Date */}
              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700">
                  Start Date
                </label>
                <DatePicker
                  selected={startDate}
                  onChange={handleStartDateChange}
                  selectsStart
                  startDate={startDate}
                  endDate={endDate}
                  minDate={new Date()}
                  dateFormat="MMMM d, yyyy"
                  className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholderText="Select start date"
                />
              </div>

              {/* End Date */}
              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700">
                  End Date
                </label>
                <DatePicker
                  selected={endDate}
                  onChange={handleEndDateChange}
                  selectsEnd
                  startDate={startDate}
                  endDate={endDate}
                  minDate={startDate || new Date()}
                  dateFormat="MMMM d, yyyy"
                  className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholderText="Select end date"
                />
              </div>
            </div>

            {/* Time Selection */}
            <div className="flex items-center space-x-4 mt-6">
              <FaClock className="text-blue-500 text-xl" />
              <h2 className="text-xl font-semibold">Select Times</h2>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Start Time */}
              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700">
                  Start Time
                </label>
                <DatePicker
                  selected={startTime}
                  onChange={setStartTime}
                  showTimeSelect
                  showTimeSelectOnly
                  timeIntervals={15}
                  timeCaption="Time"
                  dateFormat="h:mm aa"
                  className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholderText="Select start time"
                />
              </div>

              {/* End Time */}
              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700">
                  End Time
                </label>
                <DatePicker
                  selected={endTime}
                  onChange={setEndTime}
                  showTimeSelect
                  showTimeSelectOnly
                  timeIntervals={15}
                  timeCaption="Time"
                  dateFormat="h:mm aa"
                  className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholderText="Select end time"
                />
              </div>
            </div>

            {/* Trip Duration Summary */}
            {startDate && endDate && (
              <div className="mt-6 p-4 bg-blue-50 rounded-lg">
                <h3 className="text-lg font-medium text-blue-900">Trip Duration</h3>
                <p className="text-blue-700">
                  {format(startDate, 'MMMM d, yyyy')} at {startTime ? format(startTime, 'h:mm aa') : '--:--'} 
                  <FaArrowRight className="inline mx-2" />
                  {format(endDate, 'MMMM d, yyyy')} at {endTime ? format(endTime, 'h:mm aa') : '--:--'}
                </p>
              </div>
            )}

            {/* Navigation Buttons */}
            <div className="flex justify-between mt-8">
              <button
                onClick={onBack}
                className="px-6 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 transition-colors"
              >
                Back
              </button>
              <button
                onClick={handleComplete}
                disabled={!isComplete}
                className={`px-6 py-2 rounded-lg text-white transition-colors ${
                  isComplete
                    ? 'bg-blue-500 hover:bg-blue-600'
                    : 'bg-gray-300 cursor-not-allowed'
                }`}
              >
                Continue
              </button>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

export default DateSelection;
